def schedule_jobs(deps):
    """
    Given a dict mapping job names to lists of prerequisites,
    return the lexicographically smallest valid topological order as a list,
    or None if there is a cycle.

    A prerequisite omitted as a dict key is still a job with no prerequisites.
    Repeated prerequisites are treated as one dependency.
    Do not mutate the input.
    """
    # Collect all jobs: keys in deps and any prerequisites mentioned
    all_jobs = set(deps.keys())
    for job, prereqs in deps.items():
        for p in prereqs:
            all_jobs.add(p)

    # Build adjacency list and in-degree count
    # adj[u] contains v if u is a prerequisite of v (i.e., u -> v means v depends on u)
    # Actually, let's think: deps[job] = list of prerequisites. So job depends on each prereq.
    # Edge from prereq to job: prereq -> job
    adj = {job: set() for job in all_jobs}
    in_degree = {job: 0 for job in all_jobs}

    for job, prereqs in deps.items():
        # Deduplicate prerequisites
        unique_prereqs = set(prereqs)
        for p in unique_prereqs:
            # Edge from p to job
            if p not in adj[job]:  # Actually we need adj[p] to contain job
                pass
            # Let me redo: adj[p] should contain job (p -> job means job depends on p)
            if job not in adj[p]:
                adj[p].add(job)
                in_degree[job] += 1

    # Use a min-heap for lexicographically smallest order
    import heapq
    heap = []
    for job in all_jobs:
        if in_degree[job] == 0:
            heapq.heappush(heap, job)

    result = []
    while heap:
        job = heapq.heappop(heap)
        result.append(job)
        for neighbor in adj[job]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(all_jobs):
        return None

    return result
