def net_inventory(events):
    seen_ids = set()
    sku_totals = {}

    for event_id, sku, signed_delta in events:
        if event_id in seen_ids:
            continue
        seen_ids.add(event_id)
        sku_totals[sku] = sku_totals.get(sku, 0) + signed_delta

    result = []
    for sku, quantity in sku_totals.items():
        if quantity != 0:
            result.append((sku, quantity))

    result.sort()
    return result
