def traverse_rooms(graph, start):
    distances = {start: 0}
    queue = [start]
    index = 0
    while index < len(queue):
        current = queue[index]
        index += 1
        neighbors = graph.get(current, [])
        for neighbor in neighbors:
            if neighbor not in distances:
                distances[neighbor] = distances[current] + 1
                queue.append(neighbor)
    return distances
